using System.Text.Json.Serialization;
using GeminiAPIWrapper.Serialization;

namespace GeminiAPIWrapper.Models;

/// <summary>
/// Producer role of a <see cref="Content"/> message in a conversation.
/// See <see href="https://ai.google.dev/api/caching#Content"/>.
/// </summary>
[JsonConverter(typeof(LenientStringEnumConverter<Role>))]
public enum Role
{
    /// <summary>
    /// Content provided by the end user or tool caller (<c>user</c>).
    /// </summary>
    [JsonStringEnumMemberName("user")]
    User,

    /// <summary>
    /// Content generated by the model (<c>model</c>).
    /// </summary>
    [JsonStringEnumMemberName("model")]
    Model,

    /// <summary>
    /// Content produced by a tool or function execution (<c>function</c>).
    /// </summary>
    [JsonStringEnumMemberName("function")]
    Function,

    /// <summary>
    /// Fallback value used when the server returns a role not yet defined in this version of the library.
    /// </summary>
    Unknown
}
